// Package random implements the gomplate `random` template-function
// namespace: pseudo-random string/item/number generation.
//
// The behaviour (including exact error texts) mirrors the reference
// gomplate binary. Randomness comes from math/rand's global source, so
// outputs are non-deterministic; only shapes and constraints are stable.
package random

import (
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"math/rand"
	"reflect"
	"regexp"
	"strconv"
	"unicode"
	"unicode/utf8"

	"gomplate/internal/num"
)

// character sets used by the simple string generators
const (
	alphaChars    = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
	alphaNumChars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
	// default set for random.String: [a-zA-Z0-9_.-]
	defaultChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-"
)

// asciiChars is the full printable 7-bit ASCII set, including space
var asciiChars = func() []rune {
	c := make([]rune, 0, 95)
	for r := rune(32); r <= rune(126); r++ {
		c = append(c, r)
	}
	return c
}()

// Funcs is the random namespace. Its methods are the template functions.
type Funcs struct{}

// NS returns the random namespace value.
func NS() any {
	return &Funcs{}
}

// ASCII generates a random string of count characters from the printable
// 7-bit ASCII set (including space).
func (f *Funcs) ASCII(count any) (string, error) {
	return randomString(count, asciiChars)
}

// Alpha generates a random alphabetical (A-Z, a-z) string.
func (f *Funcs) Alpha(count any) (string, error) {
	return randomString(count, []rune(alphaChars))
}

// AlphaNum generates a random alphanumeric (0-9, A-Z, a-z) string.
func (f *Funcs) AlphaNum(count any) (string, error) {
	return randomString(count, []rune(alphaNumChars))
}

func randomString(count any, chars []rune) (string, error) {
	n, err := toInt64(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	// a negative length panics here, matching the reference's
	// "runtime error: makeslice: len out of range"
	out := make([]rune, n)
	for i := range out {
		out[i] = chars[rand.Intn(len(chars))]
	}
	return string(out), nil
}

// String generates a random string of count characters. With no extra
// arguments the default character set [a-zA-Z0-9_.-] is used. With one
// extra argument it's treated as a regular expression that each character
// must match. With two extra arguments they set the lower/upper bounds of
// a range of Unicode code-points (non-printable ones are discarded).
// Three or more extra arguments fall back to the default set.
func (f *Funcs) String(count any, args ...any) (string, error) {
	n, err := toInt64(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if n == 0 {
		return "", errors.New("count must be greater than 0")
	}

	var chars []rune
	switch len(args) {
	case 1:
		chars, err = charsFromRegex(fmt.Sprintf("%v", args[0]))
	case 2:
		chars, err = charsFromRange(args[0], args[1])
	default:
		chars = []rune(defaultChars)
	}
	if err != nil {
		return "", err
	}

	// negative count panics here, matching the reference
	out := make([]rune, n)
	if len(chars) == 0 {
		// matches the reference's rand.IntN(0) failure
		return "", errors.New("invalid argument to IntN")
	}
	for i := range out {
		out[i] = chars[rand.Intn(len(chars))]
	}
	return string(out), nil
}

// charsFromRegex builds the set of printable Unicode code-points that match
// the given regular expression. An empty regex selects the default set.
func charsFromRegex(expr string) ([]rune, error) {
	if expr == "" {
		return []rune(defaultChars), nil
	}
	re, err := regexp.Compile(expr)
	if err != nil {
		return nil, err
	}
	chars := []rune{}
	for r := rune(0); r <= utf8.MaxRune; r++ {
		if unicode.IsPrint(r) && re.MatchString(string(r)) {
			chars = append(chars, r)
		}
	}
	return chars, nil
}

// charsFromRange builds the set of printable code-points between the lower
// and upper bounds, inclusive. Bounds may be numbers or single-character
// strings.
func charsFromRange(lowerIn, upperIn any) ([]rune, error) {
	lower, upper, err := toCodepoints(lowerIn, upperIn)
	if err != nil {
		return nil, err
	}
	chars := []rune{}
	for r := lower; r <= upper; r++ {
		if unicode.IsPrint(r) {
			chars = append(chars, r)
		}
	}
	if len(chars) == 0 {
		return nil, fmt.Errorf("no printable codepoints found between U%q and U%q", lower, upper)
	}
	return chars, nil
}

// toCodepoints converts lower/upper bounds to runes. When both bounds are
// single-character strings, the characters themselves are used. When both
// are (longer) strings, they're parsed as base-prefix-aware integers and
// parse errors are returned verbatim. Otherwise both go through the lenient
// numeric conversion with labelled errors.
func toCodepoints(lowerIn, upperIn any) (rune, rune, error) {
	ls, lok := lowerIn.(string)
	us, uok := upperIn.(string)
	if lok && uok {
		if utf8.RuneCountInString(ls) == 1 && utf8.RuneCountInString(us) == 1 {
			l, _ := utf8.DecodeRuneInString(ls)
			u, _ := utf8.DecodeRuneInString(us)
			return l, u, nil
		}
		l, err := strconv.ParseInt(ls, 0, 64)
		if err != nil {
			return 0, 0, err
		}
		u, err := strconv.ParseInt(us, 0, 64)
		if err != nil {
			return 0, 0, err
		}
		return rune(l), rune(u), nil
	}

	l, err := toInt64(lowerIn)
	if err != nil {
		return 0, 0, fmt.Errorf("lower must be an integer: %w", err)
	}
	u, err := toInt64(upperIn)
	if err != nil {
		return 0, 0, fmt.Errorf("upper must be an integer: %w", err)
	}
	return rune(l), rune(u), nil
}

// Item picks a random element from a slice or array.
func (f *Funcs) Item(v any) (any, error) {
	rv := reflect.ValueOf(v)
	if rv.Kind() != reflect.Slice && rv.Kind() != reflect.Array {
		return nil, fmt.Errorf("expected an array or slice, but got a %T", rv)
	}
	if rv.Len() == 0 {
		return nil, errors.New("expected a non-empty array or slice")
	}
	return rv.Index(rand.Intn(rv.Len())).Interface(), nil
}

// Number picks a random integer. With no arguments the range is 0-100;
// with one argument, 0 to that value; with two, min to max (inclusive).
// More arguments fall back to the default range.
func (f *Funcs) Number(args ...any) (int64, error) {
	min, max := int64(0), int64(100)
	var err error
	switch len(args) {
	case 1:
		max, err = toInt64(args[0])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	case 2:
		min, err = toInt64(args[0])
		if err != nil {
			return 0, fmt.Errorf("min must be a number: %w", err)
		}
		max, err = toInt64(args[1])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	}

	if min > max {
		return 0, fmt.Errorf("min must not be greater than max (was %d, %d)", min, max)
	}
	if max-min >= math.MaxInt64>>1 {
		return 0, fmt.Errorf("spread between min and max too high - must not be greater than 63-bit maximum (%d - %d = %d)", max, min, max-min)
	}
	n := max - min + 1
	if n <= 0 {
		// overflowed; matches the reference's rand.Int64N failure
		return 0, errors.New("invalid argument to Int64N")
	}
	return min + rand.Int63n(n), nil
}

// Float picks a random floating-point number. With no arguments the range
// is [0.0, 1.0); with one argument, [0.0, max); with two, [min, max).
// More arguments fall back to the default range.
func (f *Funcs) Float(args ...any) (float64, error) {
	min, max := 0.0, 1.0
	var err error
	switch len(args) {
	case 1:
		max, err = toFloat64(args[0])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	case 2:
		min, err = toFloat64(args[0])
		if err != nil {
			return 0, fmt.Errorf("min must be a number: %w", err)
		}
		max, err = toFloat64(args[1])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	}
	return min + rand.Float64()*(max-min), nil
}

// toInt64 coerces v to an int64, mirroring the reference's conversion:
// numeric and boolean values convert directly (floats truncate), strings
// are parsed base-prefix-aware with a float fallback, and anything else is
// an error.
func toInt64(v any) (int64, error) {
	switch n := v.(type) {
	case string:
		return stringToInt64(n)
	case json.Number:
		return stringToInt64(n.String())
	case int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64,
		float32, float64, bool:
		return num.ToInt64(v), nil
	default:
		return 0, fmt.Errorf("could not convert %v to int64", v)
	}
}

func stringToInt64(s string) (int64, error) {
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		return i, nil
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, fmt.Errorf("could not convert %q to int64: %w", s, err)
	}
	return int64(f), nil
}

// toFloat64 coerces v to a float64 with the same rules as toInt64.
func toFloat64(v any) (float64, error) {
	switch n := v.(type) {
	case string:
		return stringToFloat64(n)
	case json.Number:
		return stringToFloat64(n.String())
	case int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64,
		float32, float64, bool:
		return num.ToFloat64(v), nil
	default:
		return 0, fmt.Errorf("could not convert %v to float64", v)
	}
}

func stringToFloat64(s string) (float64, error) {
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		return float64(i), nil
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, fmt.Errorf("could not convert %q to float64: %w", s, err)
	}
	return f, nil
}
